import React from 'react';
import { useNavigate } from 'react-router-dom';
import { Globe, ArrowLeft, Building2, ShieldCheck, Mail, Briefcase } from 'lucide-react';

const HrRegistration = () => {
  const navigate = useNavigate();
  const bgImage = "https://i.pinimg.com/1200x/3d/da/0d/3dda0d2769ba87e3b59597ba56f6548e.jpg";

  return (
    <div className="min-h-screen flex flex-col items-center py-12 px-4 relative overflow-hidden font-sans"
      style={{ backgroundImage: `linear-gradient(rgba(15, 23, 42, 0.9), rgba(30, 58, 138, 0.8)), url(${bgImage})`, backgroundSize: 'cover', backgroundAttachment: 'fixed' }}>
      
      {/* Decorative Blur Orbs */}
      <div className="absolute -top-20 -right-20 w-96 h-96 bg-blue-500/20 rounded-full blur-[120px]"></div>

      <div className="w-full max-w-4xl flex justify-between items-center mb-8 z-10">
        <div className="flex items-center gap-2 text-white font-black text-2xl tracking-tighter">
          <div className="bg-white/10 p-2 rounded-lg backdrop-blur-md border border-white/20">
            <Globe size={24} className="text-blue-400" />
          </div>
          Talent<span className="text-blue-400">Pool</span>
        </div>
        <button onClick={() => navigate('/register')} className="flex items-center gap-2 text-white/60 hover:text-white font-bold text-xs uppercase tracking-widest transition-all">
          <ArrowLeft size={16} /> Back to Selection
        </button>
      </div>

      <div className="bg-white/10 backdrop-blur-2xl w-full max-w-3xl rounded-[3rem] shadow-2xl border border-white/10 overflow-hidden z-10 animate-in fade-in slide-in-from-bottom-5 duration-700">
        <div className="p-10 border-b border-white/10 text-center bg-white/5">
          <h1 className="text-3xl font-black text-white tracking-tight">Employer Account</h1>
          <p className="text-blue-200/60 text-sm mt-2 font-medium">Register your organization to access verified talent.</p>
        </div>

        <form className="p-10 space-y-10">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
            
            {/* Left Column: Personal */}
            <div className="space-y-6">
              <div className="flex items-center gap-3 text-blue-400 font-black text-xs uppercase tracking-[0.2em]">
                <Mail size={18} /> HR Identity
              </div>
              <input type="text" placeholder="Full Name" className="glass-input-blue" />
              <input type="email" placeholder="Work Email (@company)" className="glass-input-blue" />
              <input type="password" placeholder="Password" className="glass-input-blue" />
            </div>

            {/* Right Column: Company */}
            <div className="space-y-6">
              <div className="flex items-center gap-3 text-blue-400 font-black text-xs uppercase tracking-[0.2em]">
                <Building2 size={18} /> Company Credentials
              </div>
              <input type="text" placeholder="Legal Entity Name" className="glass-input-blue" />
              <input type="url" placeholder="Company Website URL" className="glass-input-blue" />
              <select className="glass-input-blue appearance-none">
                <option className="bg-slate-900">Industry Type</option>
                <option className="bg-slate-900">Technology</option>
                <option className="bg-slate-900">Healthcare</option>
              </select>
            </div>
          </div>

          {/* Verification Docs */}
          <section className="space-y-6">
            <div className="flex items-center gap-3 text-blue-400 font-black text-xs uppercase tracking-[0.2em]">
              <ShieldCheck size={18} /> Business Authentication
            </div>
            <div className="border-2 border-dashed border-white/10 rounded-[2rem] p-10 flex flex-col items-center justify-center bg-white/5 hover:bg-white/10 transition-all cursor-pointer group">
              <Briefcase size={32} className="text-blue-400 mb-3 group-hover:scale-110 transition-transform" />
              <p className="text-white font-bold tracking-tight">Upload Incorporation Certificate</p>
              <p className="text-[10px] text-white/30 mt-1 uppercase font-black tracking-widest">Business ID / License (PDF/JPG)</p>
            </div>
          </section>

          <button type="submit" className="w-full bg-gradient-to-r from-blue-600 to-cyan-600 text-white font-black py-5 rounded-2xl shadow-xl hover:brightness-110 transition-all transform active:scale-[0.98] tracking-[0.2em] text-sm">
            
          </button>
        </form>
      </div>

      <style>{`
        .glass-input-blue {
          width: 100%; padding: 1rem 1.5rem; background: rgba(255, 255, 255, 0.05);
          border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 1.25rem;
          color: white; font-size: 0.875rem; outline: none; transition: all 0.3s;
        }
        .glass-input-blue:focus {
          border-color: #3b82f6; background: rgba(255, 255, 255, 0.1);
          box-shadow: 0 0 20px rgba(59, 130, 246, 0.2);
        }
        .glass-input-blue::placeholder { color: rgba(255, 255, 255, 0.3); }
      `}</style>
    </div>
  );
};

export default HrRegistration;
